const tabId = 730410078;

const cars = await browserjs(tabId, () => {
  // Let's inspect article elements or car cards
  const articles = Array.from(document.querySelectorAll('article, [data-qa="car-tile"], [class*="car-tile"]'));
  return articles.map(a => ({
    text: a.innerText,
    links: Array.from(a.querySelectorAll('a')).map(l => ({ href: l.href, text: l.innerText }))
  }));
});

console.log("Found cars count:", cars.length);
if (cars.length > 0) {
  console.log("Sample car 0:", JSON.stringify(cars[0], null, 2));
  console.log("Sample car 1:", JSON.stringify(cars[1], null, 2));
} else {
  // Let's look for links with /car/ in them
  const carLinks = Array.from(document.querySelectorAll('a[href*="/car/"]')).map(a => ({
    href: a.href,
    text: a.innerText
  }));
  console.log("Car links:", JSON.stringify(carLinks.slice(0, 10), null, 2));
}

